head.script:
/**
 * @component
 * @componentName udc_cmm
 * @pluginName
 * @company
 * @developer
 * @category /cm/gcc
 * @notSupportBrowser
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description
 * @width
 * @height
 * @license
 * @imagePath
 * @homepage
 */

scwin.onpageload = function() {

};

/**
 * @method
 * @name includes
 * @description includes
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.includes = function(opt = {}) {
    return Object.entries(opt.source).every(([k, v]) => opt.target[k] === v);
};

/**
 * @method
 * @name getLocalStorage
 * @description getLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.getLocalStorage = function(opt = {}) {
    if (typeof(Storage) !== "undefined") {
        return localStorage.getItem(opt.key);
    }
    return null;
};

/**
 * @method
 * @name setLocalStorage
 * @description setLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.setLocalStorage = function(opt = {}) {
    if (typeof(Storage) !== "undefined") {
        localStorage.setItem(opt.key, opt.value);
    }
};

/**
 * @method
 * @name removeLocalStorage
 * @description removeLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.removeLocalStorage = function(opt = {}) {
    if (typeof(Storage) !== "undefined") {
        removeLocalStorageItem(opt.key);
    }
};

/**
 * @method
 * @name readLocalStorage
 * @description readLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.readLocalStorage = function(opt = {}) {
    var raw = $c.cmm.getLocalStorage({ key : opt.key });
    return raw ? JSON.parse(raw) : [];
};

/**
 * @method
 * @name writeLocalStorage
 * @description writeLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.writeLocalStorage = function(opt = {}) {
    $c.cmm.setLocalStorage({ key : opt.key, value : JSON.stringify(opt.rows) });
};

/**
 * @method
 * @name selectLocalStorage
 * @description selectLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.selectLocalStorage = function(opt = {}) {
    var rows = $c.cmm.readLocalStorage({ key : opt.key });
    if (opt.data !== undefined) {
        var row = rows.find(function(row) { return $c.cmm.includes({target : row, source : opt.data}); });
        return row;
    }
    return rows;
};

/**
 * @method
 * @name insertLocalStorage
 * @description insertLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.insertLocalStorage = function(opt = {}) {
    var rows = $c.cmm.readLocalStorage({ key : opt.key });
    var nextId = rows.reduce(function(max, row) { return Math.max(max, row.id); }, 0) + 1;
    var row = {id : nextId, ...opt.data};
    rows.push(row);
    $c.cmm.writeLocalStorage({ key : opt.key, rows : rows });
    return row;
};

/**
 * @method
 * @name updateLocalStorage
 * @description updateLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.updateLocalStorage = function(opt = {}) {
    var rows = $c.cmm.readLocalStorage({ key : opt.key });
    var row = rows.find(function(r) { return r.id === opt.data.id; });
    if (row) {
        Object.assign(row, opt.data);
        $c.cmm.writeLocalStorage({ key : opt.key, rows : rows });
    }
    return row;
};

/**
 * @method
 * @name deleteLocalStorage
 * @description deleteLocalStorage
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.deleteLocalStorage = function(opt = {}) {
    var rows = $c.cmm.readLocalStorage({ key : opt.key });
    var row = rows.find(function(row) { return row.id === opt.data.id; });
    $c.cmm.writeLocalStorage({ key : opt.key, rows : rows.filter(function(row) { return row.id !== opt.data.id; }) });
    return row;
};
